window.DRIVE_FOLDERS_MAP = DRIVE_FOLDERS_MAP;

// Helper: Normalize Arabic string for robust fuzzy matching
function normalizeArabic(str) {
  if (!str) return '';
  return str.toString().trim()
    .replace(/[\u064B-\u065F\u0670]/g, '') // Remove tashkeel
    .replace(/[إأآا]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

// Find closest Google Drive folder URL for a given course name
window.getDriveFolderForCourse = function(courseName) {
  if (!courseName) return "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  const norm = normalizeArabic(courseName);

  for (const [folderName, info] of Object.entries(DRIVE_FOLDERS_MAP)) {
    const normFolder = normalizeArabic(folderName);
    if (normFolder === norm || norm.includes(normFolder) || normFolder.includes(norm)) {
      return info.url;
    }
  }

  // Key word heuristics
  if (norm.includes('كائن') || norm.includes('اوبجكت') || norm.includes('oop')) {
    return DRIVE_FOLDERS_MAP['البرمجة الموجهة للكائنات object oriented programming']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('تفاضل') || norm.includes('تكامل') || norm.includes('كالكولاس')) {
    if (norm.includes('2')) return DRIVE_FOLDERS_MAP['تفاضل وتكامل (2) Calculus']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
    return DRIVE_FOLDERS_MAP['تفاضل وتكامل (1) Calculus']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('هياكل') || norm.includes('بيانات')) {
    if (norm.includes('مستودع')) return DRIVE_FOLDERS_MAP['(Data Warehousing)مستودعات البيانات CIS']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
    if (norm.includes('تنقيب')) return DRIVE_FOLDERS_MAP['التنقيب عن البيانات Data Mining']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
    if (norm.includes('قواعد')) return DRIVE_FOLDERS_MAP['إدارة نظم قواعد البيانات(cis)']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
    return DRIVE_FOLDERS_MAP['هياكل البيانات']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('شبك')) {
    if (norm.includes('لاسلك')) return DRIVE_FOLDERS_MAP['شبكات الحاسوب اللاسلكيه wireless computer networks']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
    return DRIVE_FOLDERS_MAP['مبادئ شبكات الحاسوب']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('تشغيل') || norm.includes('os')) {
    return DRIVE_FOLDERS_MAP['مبادئ نظم التشغبل']?.url || DRIVE_FOLDERS_MAP['مبادءئ نظم التشغيل']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('منطق')) {
    return DRIVE_FOLDERS_MAP['المنطق الرقمي']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('جافا') || norm.includes('java')) {
    return DRIVE_FOLDERS_MAP['البرمجة بلغة جافا']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('ويب') || norm.includes('انترنت')) {
    return DRIVE_FOLDERS_MAP['برمجة تطبيقات الانترنت']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('خوارزم')) {
    return DRIVE_FOLDERS_MAP['تحليل وتصميم الخوارزميات (السلايدات)']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('احصاء') || norm.includes('احتمال')) {
    return DRIVE_FOLDERS_MAP['احتمال واحصاء probability and Statististics']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('تحليل عددي')) {
    return DRIVE_FOLDERS_MAP['مبادئ التحليل العددي Principles of Numerical Analysis']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('متقطع') || norm.includes('منفصل')) {
    return DRIVE_FOLDERS_MAP['الهياكل والرياضيات المنفصله Structure and Discrete Mathematics']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('حاسوب 1') || norm.includes('حاسوب 99') || norm.includes('مهارات الحاسوب')) {
    return DRIVE_FOLDERS_MAP['حاسوب']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('عربي') || norm.includes('لغه عربيه')) {
    return DRIVE_FOLDERS_MAP['عربي']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('وطني') || norm.includes('عسكري')) {
    return DRIVE_FOLDERS_MAP['عسكرية + وطنية']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }
  if (norm.includes('انجليز') || norm.includes('english')) {
    return DRIVE_FOLDERS_MAP['English']?.url || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
  }

  return "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link";
};

// Universal Material Package Resolver for 100% of Courses
window.getCourseMaterialPackage = function(courseName, cohort = 'all') {
  if (!courseName) return null;
  const norm = normalizeArabic(courseName);

  // 1. Check if course maps to one of the 17 fully extracted local courses
  let localKey = null;
  if (norm.includes('مترجم')) localKey = 'compiler';
  else if (norm.includes('مدمج')) localKey = 'embedded';
  else if (norm.includes('احتساب') || norm.includes('اتمت') || (norm.includes('حوسب') && norm.includes('نظري')) || norm.includes('النظريه الاحتسابيه')) localKey = 'automata';
  else if (norm.includes('لاسلك') || norm.includes('تراسل الشبكات')) localKey = 'wireless';
  else if (norm.includes('معماري')) localKey = 'architecture';
  else if (norm.includes('سحاب')) localKey = 'cloud';
  else if (norm.includes('وسائط')) localKey = 'multimedia';
  else if (norm.includes('صور') && (norm.includes('رؤي') || norm.includes('رؤيا'))) localKey = 'image_processing';
  else if (norm.includes('استرجاع')) localKey = 'information_retrieval';
  else if (norm.includes('تحليل وتصميم نظم') || norm.includes('تحليل وتصميم النظم')) localKey = 'systems_analysis';
  else if (norm.includes('قواعد البيانات 2') || (norm.includes('اداره قواعد البيانات') && norm.includes('2'))) localKey = 'db2';
  else if (norm.includes('ذكاء اصطناعي متقدم')) localKey = 'advanced_ai';
  else if (norm.includes('ذكاء اصطناعي')) localKey = 'ai';
  else if (norm.includes('هندسه البرمجيات الحديثه')) localKey = 'software_engineering';
  else if (norm.includes('امن الحاسوب') || norm.includes('امن المعلومات')) localKey = 'security';
  else if (norm.includes('مواضيع خاصه في علم الحاسوب')) localKey = 'topics';
  else if (norm.includes('تعلم الاله') || norm.includes('تعلم الال')) localKey = 'machine_learning';

  // Exceptions where names contain common words but shouldn't map to local package
  if (norm.includes('نماذج وقواعد البيانات') || 
      norm.includes('مبادئ هندسه البرمجيات') || 
      norm === 'شبكات الحاسوب' || 
      norm.includes('مبادئ شبكات الحاسوب') || 
      norm.includes('الحوسبه فائقه الاداء')) {
    localKey = null;
  }

  let mat = null;
  if (localKey && MATERIALS_DATABASE[localKey]) {
    // Clone local course object so we can append custom files without mutating base
    const base = MATERIALS_DATABASE[localKey];
    mat = {
      ...base,
      categoryCounts: { ...base.categoryCounts },
      files: [ ...base.files ],
      directBooks: base.files.filter(f => f.category === 'books'),
      driveUrl: window.getDriveFolderForCourse(courseName) || base.driveUrl || "https://drive.google.com/drive/folders/1aEPGZ_NeJDN96k4LgvCdlOILQdIsRGD8?usp=drive_link"
    };
  } else {
    // Generate full dynamic course package for this course!
    const driveUrl = window.getDriveFolderForCourse(courseName);
    const slug = 'course-' + encodeURIComponent(norm.replace(/\s+/g, '-'));
    mat = {
      id: slug,
      rawName: courseName,
      title: courseName,
      titleEn: 'Course Materials & Syllabus',
      category: norm.includes('اختيار') ? 'elective' : 'compulsory',
      totalFiles: 0,
      totalSizeBytes: 0,
      totalSizeFormatted: '0 MB',
      categoryCounts: {
        books: 0,
        slides: 0,
        exams: 0,
        summaries: 0,
        labs: 0,
        videos: 0,
        other: 0
      },
      directBooks: [],
      files: [],
      driveUrl: driveUrl,
      isDynamic: true
    };
  }

  // 2. Load custom user-added files from localStorage for this course
  try {
    const storageKey = 'CUSTOM_COURSE_FILES_' + encodeURIComponent(norm);
    const stored = localStorage.getItem(storageKey);
    if (stored) {
      const customFiles = JSON.parse(stored);
      if (Array.isArray(customFiles) && customFiles.length > 0) {
        customFiles.forEach(cf => {
          if (!mat.files.some(f => f.id === cf.id || f.name === cf.name)) {
            mat.files.unshift(cf);
            mat.totalFiles++;
            const cat = cf.category || 'other';
            if (mat.categoryCounts[cat] !== undefined) {
              mat.categoryCounts[cat]++;
            } else {
              mat.categoryCounts.other = (mat.categoryCounts.other || 0) + 1;
            }
            if (cat === 'books') {
              mat.directBooks.unshift(cf);
            }
          }
        });
      }
    }
  } catch (err) {
    console.warn('Error loading custom files for course:', err);
  }

  return mat;
};
